	// Defaults to true. Possible values: true, false. Defaults to true.
	IsVisible *bool
	// Some optional notes. This can contain limited HTML for styling. Allowed tags:
	// a, p, div, h1, h2, h3, h4, h5, h6, ul, ol, li, blockquote, b, i, s, u, o,
	// sup, sub, ins, del, strong, strike, tt, code, big, small, br, span, em.
	// Allowed inline CSS rules: background, background-color, color, font,
	// font-size, font-weight, font-style, text-align, text-indent, text-decoration.
	Notes *string
	// Pre-calculations that are each stored in a variable, which can be used in the
	// salary type's main calculation .
