	// The amount of the salary statement is calculated here. Can contain a formula
	// with limited JavaScript code.
	Calculation *string
	// The salary certificate code to add the result of this salary type to. Max
	// length: 10.
	CertificateCode *string
	// The ID of the financial account on the credit side. This account will be used
	// to generate the book entries.
